for (const cancellation of ["client disconnect", "Server shutdown"] as const) {
  test(`Hosted configuration probes abort HTTPS on ${cancellation}`, {
    timeout: 5_000
  }, async () => {
    const directory = await mkdtemp(path.join(
      os.tmpdir(),
      "convene-wire-hosted-probe-cancel-"
    ));
    let markStarted!: () => void;
    const started = new Promise<void>((resolve) => {
      markStarted = resolve;
    });
    let markAborted!: () => void;
    const aborted = new Promise<void>((resolve) => {
      markAborted = resolve;
    });
    const hostedFetch: typeof fetch = async (_input, init) => {
      assert.ok(init?.signal);
      markStarted();
      return new Promise<Response>((_resolve, reject) => {
        const rejectAbort = () => {
          markAborted();
          reject(new DOMException("Aborted", "AbortError"));
        };
        if (init.signal!.aborted) rejectAbort();
        else init.signal!.addEventListener("abort", rejectAbort, { once: true });
      });
    };
    const app = await createServerApp({
      databasePath: path.join(directory, "server.sqlite"),
      hostedFetch,
      clock: () => now,
      logger: false
    });
    const caller = new AbortController();
    try {
      await app.ready();
      const { authorization, teamId } = await bootstrap(app);
      const address = await app.listen({ port: 0, host: "127.0.0.1" });
      const request = Promise.allSettled([fetch(
        `${address}/api/teams/${teamId}/hosted-agent-tests`,
        {
          method: "POST",
          headers: { authorization, "content-type": "application/json" },
          body: JSON.stringify({
            provider: "openai_responses",
            model: "gpt-5.4-mini",
            apiKey
          }),
          signal: caller.signal
        }
      )]);
      await started;
      const closing = cancellation === "Server shutdown"
        ? app.close()
        : undefined;
      if (cancellation === "client disconnect") caller.abort();
      await aborted;
      const [settled] = await request;
      if (cancellation === "client disconnect") {
        assert.equal(settled?.status, "rejected");
      } else {
        assert.equal(settled?.status, "fulfilled");
        if (settled?.status !== "fulfilled") {
          throw new Error("Shutdown did not settle the probe response");
        }
        assert.equal(settled.value.status, 200);
        assert.equal(settled.value.headers.get("cache-control"), "no-store");
        const observation = await settled.value.json() as {
          status: string;
          failureCode: string;
        };
        assert.equal(observation.status, "failed");
        assert.equal(observation.failureCode, "HOSTED_PROVIDER_PROBE_CANCELED");
      }
      await closing;
    } finally {
      caller.abort();
      await app.close();
    }
  });
}

async function withRequestCancellation<Result>(
  request: FastifyRequest,
  reply: FastifyReply,
  operation: (signal: AbortSignal) => Promise<Result>
): Promise<Result> {
  const controller = new AbortController();
  const abort = (): void => controller.abort();
  request.raw.once("aborted", abort);
  reply.raw.once("close", abort);
  if (request.raw.aborted || reply.raw.destroyed) abort();
  try {
    return await operation(controller.signal);
  } finally {
    request.raw.off("aborted", abort);
    reply.raw.off("close", abort);
  }
}

export function registerHostedAgentRoutes({
  app,
  clock,
  hostedAgents,
  principal
}: ServerRouteContext & {
  hostedAgents: HostedAgentConfigurationService;
}): void {
  app.get<{ Params: { teamId: string } }>(
    "/api/teams/:teamId/hosted-agents",
    async (request, reply) => {
      noStore(reply);
      return hostedAgents.list(principal(request), request.params.teamId);
    }
  );

  app.post<{ Params: { teamId: string } }>(
    "/api/teams/:teamId/hosted-agent-tests",
    async (request, reply) => {
      noStore(reply);
      const body = bodyObject(request);
      rejectProviderEndpointFields(body);
      return withRequestCancellation(request, reply, (signal) =>
        hostedAgents.testConnection(principal(request), {
          teamId: request.params.teamId,
          provider: requiredString(body.provider, "provider", 80),
          model: requiredString(body.model, "model", 160),
          apiKey: requiredString(body.apiKey, "apiKey", 512),
          now: clock(),
          signal
        })
      );
    }
  );

